describe('Form Auto-Save Functionality', () => {
    beforeEach(() => {
        cy.visit('/form-page'); // Replace with the actual URL of the form page
    });

    it('should auto-save the form as a draft every 30 seconds', () => {
        cy.get('input[name="title"]').type('Test Draft Title');
        cy.get('textarea[name="description"]').type('This is a test description.');

        cy.wait(30000); // Wait for 30 seconds to allow auto-save

        cy.get('.draft-notification').should('be.visible').and('contain', 'Draft saved successfully');
        cy.get('.draft-title').should('contain', 'Test Draft Title');
        cy.get('.draft-description').should('contain', 'This is a test description.');
    });

    it('should not auto-save if the form is empty', () => {
        cy.get('input[name="title"]').clear();
        cy.get('textarea[name="description"]').clear();

        cy.wait(30000); // Wait for 30 seconds to allow auto-save

        cy.get('.draft-notification').should('not.exist');
    });
});
